(25961, 'Acts 21:13', 'Acts', 21, 13, 'خو پولوس په ځواب کې وویل: «تاسو څه کوئ؟ تاسو ولې ژاړئ او زما زړه ماتوئ؟ زه نه یوازې دې ته تیار یم چې بندي شم، بلکې دې ته هم تیار یم چې د څښتن عیسی په خاطر په اورشلیم کې مړ شم.»', 'خو پولوس په جواب کې وویل: «تاسو چه کوی؟ تاسو ولې ژاری او زما زره ماتوی؟ زه نه یوازې دې ته تیار یم چې بندی شم، بلکې دې ته هم تیار یم چې د چشتن عیسی په خاطر په اورشلیم کې مر شم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25962, 'Acts 21:14', 'Acts', 21, 14, 'مونږ ونه شو کولای چې هغه ته قناعت ورکړو، نو غلي شولو او ومو ویل: «څه چې د څښتن رضا وي هماغسې دې وشي.»', 'مونز ونه شو کولای چې هغه ته قناعت ورکرو، نو غلی شولو او ومو ویل: «چه چې د چشتن رضا وی هماغسې دې وشی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25963, 'Acts 21:15', 'Acts', 21, 15, 'څو ورځې وروسته مونږ سفر ته تیاری ونیوه او اورشلیم ته روان شولو.', 'چو ورجې وروسته مونز سفر ته تیاری ونیوه او اورشلیم ته روان شولو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25964, 'Acts 21:16', 'Acts', 21, 16, 'د قیصریې څو شاګردان زمونږ سره ملګري شول او مونږ یې د مناسون کور ته چې د قبرس څخه ؤ او د لومړنیو ایماندارانو څخه ؤ، د اوسېدلو دپاره بوتلو. د یعقوب او د کلیسا د مشرانو سره د پولوس لیدنه', 'د قیصریې چو شاګردان زمونز سره ملګری شول او مونز یې د مناسون کور ته چې د قبرس چخه و او د لومرنیو ایماندارانو چخه و، د اوسېدلو دپاره بوتلو. د یعقوب او د کلیسا د مشرانو سره د پولوس لیدنه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25965, 'Acts 21:17', 'Acts', 21, 17, 'کله چې مونږ اورشلیم ته ورسېدلو، نو ایماندارانو مونږ ته تود هرکلی ووایه.', 'کله چې مونز اورشلیم ته ورسېدلو، نو ایماندارانو مونز ته تود هرکلی ووایه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25966, 'Acts 21:18', 'Acts', 21, 18, 'بله ورځ پولوس زمونږ سره د یعقوب د لیدلو دپاره لاړ او د کلیسا ټول مشران هم په هغه ځای کې حاضر وو.', 'بله ورج پولوس زمونز سره د یعقوب د لیدلو دپاره لار او د کلیسا تول مشران هم په هغه جای کې حاضر وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25967, 'Acts 21:19', 'Acts', 21, 19, 'پولوس په هغوی باندې سلام واچاوه او هغوی ته یې د هغو کارونو په هکله پوره راپور ورکړ چې خدای د هغه په وسیله په غیریهودیانو کې کړي وو.', 'پولوس په هغوی باندې سلام واچاوه او هغوی ته یې د هغو کارونو په هکله پوره راپور ورکر چې خدای د هغه په وسیله په غیریهودیانو کې کری وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25968, 'Acts 21:20', 'Acts', 21, 20, 'کله چې هغوی دا واورېدل، نو د خدای ثنا یې وویله. بیا هغوی پولوس ته وویل: «ای وروره، ته وینې چې په یهودیانو کې په زرګونو خلکو ایمان راوړی دی او هغوی د موسی په شریعت باندې ټینګ ولاړ دي.', 'کله چې هغوی دا واورېدل، نو د خدای ثنا یې وویله. بیا هغوی پولوس ته وویل: «ای وروره، ته وینې چې په یهودیانو کې په زرګونو خلکو ایمان راوری دی او هغوی د موسی په شریعت باندې تینګ ولار دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25969, 'Acts 21:21', 'Acts', 21, 21, 'هغوی ته ستا په هکله ویل شوي دي چې ته هغو یهودیانو ته چې د غیریهودیانو په هېوادونو کې اوسیږي، تعلیم ورکوې چې د موسی شریعت پرېږدي. همدارنګه هغوی ته وایې چې خپل اولادونه مه سنتوئ او د یهودیانو د رواجونو څخه پیروي مه کوئ.', 'هغوی ته ستا په هکله ویل شوی دی چې ته هغو یهودیانو ته چې د غیریهودیانو په هېوادونو کې اوسیزی، تعلیم ورکوې چې د موسی شریعت پرېزدی. همدارنګه هغوی ته وایې چې خپل اولادونه مه سنتوی او د یهودیانو د رواجونو چخه پیروی مه کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25970, 'Acts 21:22', 'Acts', 21, 22, 'هغوی خامخا ستاسو د راتللو څخه خبریږي، نو بیا څه وکړو؟', 'هغوی خامخا ستاسو د راتللو چخه خبریزی، نو بیا چه وکرو؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25971, 'Acts 21:23', 'Acts', 21, 23, 'بیا هرڅه چې مونږ درته وایو هماغسې وکړه. دلته څلور کسان دي چې نذر یې منلی دی.', 'بیا هرچه چې مونز درته وایو هماغسې وکره. دلته چلور کسان دی چې نذر یې منلی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25972, 'Acts 21:24', 'Acts', 21, 24, 'د هغوی سره لاړ شه او په ګډه ورسره د پاکوالي مراسم په ځای کړه او هغوی ته پیسې ورکړه چې خپل سرونه وخرایي. نو په دې ډول به هغوی ټول په دې پوه شي څه چې ستا په هکله ویل شوي وو هغه رښتیا نه دي، بلکې ته په خپله هم د موسی د شریعت سره سم خپل ژوند تېروې.', 'د هغوی سره لار شه او په ګده ورسره د پاکوالی مراسم په جای کره او هغوی ته پیسې ورکره چې خپل سرونه وخرایی. نو په دې دول به هغوی تول په دې پوه شی چه چې ستا په هکله ویل شوی وو هغه رشتیا نه دی، بلکې ته په خپله هم د موسی د شریعت سره سم خپل ژوند تېروې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25973, 'Acts 21:25', 'Acts', 21, 25, 'خو د هغو غیریهودیانو په هکله چې ایمانداران شوي دي، مونږ هغوی ته خپله پرېکړه په لیکلې توګه لېږلې ده چې هغوی باید د هغو خوړو څخه چې بتانو ته وړاندې کیږي، د وینې د خوړلو څخه، د هغه حیوان د غوښې د خوړلو څخه چې زندۍ شوی وي او د جنسي بد‌اخلاقۍ څخه خپل ځانونه وساتي.»', 'خو د هغو غیریهودیانو په هکله چې ایمانداران شوی دی، مونز هغوی ته خپله پرېکره په لیکلې توګه لېزلې ده چې هغوی باید د هغو خورو چخه چې بتانو ته وراندې کیزی، د وینې د خورلو چخه، د هغه حیوان د غوشې د خورلو چخه چې زندی شوی وی او د جنسی بد‌اخلاقی چخه خپل جانونه وساتی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25974, 'Acts 21:26', 'Acts', 21, 26, 'نو بله ورځ پولوس هغه څلور تنه د ځان سره بوتلل او د هغوی سره یې د پاکوالي مراسم سرته ورسول. بیا هغه د خدای کور ته لاړ چې هغوی ته خبر ورکړي چې په څو ورځو کې به د پاکوالي مراسم پوره کیږي او له هغې وروسته به د هر یو دپاره قرباني وړاندې کړای شي. پولوس د خدای په کور کې نیول کیږي', 'نو بله ورج پولوس هغه چلور تنه د جان سره بوتلل او د هغوی سره یې د پاکوالی مراسم سرته ورسول. بیا هغه د خدای کور ته لار چې هغوی ته خبر ورکری چې په چو ورجو کې به د پاکوالی مراسم پوره کیزی او له هغې وروسته به د هر یو دپاره قربانی وراندې کرای شی. پولوس د خدای په کور کې نیول کیزی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25975, 'Acts 21:27', 'Acts', 21, 27, 'د پاکوالي د مراسمو اووه ورځنۍ دوره لا پای ته نه وه رسېدلې چې د اسیا د ولایت ځینو یهودیانو پولوس د خدای په کور کې ولیده. هغوی خلک ولمسول او پولوس یې ونیوه', 'د پاکوالی د مراسمو اووه ورجنی دوره لا پای ته نه وه رسېدلې چې د اسیا د ولایت جینو یهودیانو پولوس د خدای په کور کې ولیده. هغوی خلک ولمسول او پولوس یې ونیوه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25976, 'Acts 21:28', 'Acts', 21, 28, 'او چیغې یې ووهلې: «ای د اسراییلو خلکو، مرسته وکړئ او د دې سړي په خلاف زمونږ سره یوځای شئ. دا هغه سړی دی چې هر‌چېرته ځي او زمونږ د قوم، د موسی د شریعت او د خدای د کور په ضد هرچا ته تعلیم ورکوي. برسېره پر‌دې هغه یونانیان هم د خدای کور ته راوستلي دي او دا سپېڅلی ځای یې ورباندې ناپاکه کړی دی.»', 'او چیغې یې ووهلې: «ای د اسراییلو خلکو، مرسته وکری او د دې سری په خلاف زمونز سره یوجای شی. دا هغه سری دی چې هر‌چېرته جی او زمونز د قوم، د موسی د شریعت او د خدای د کور په ضد هرچا ته تعلیم ورکوی. برسېره پر‌دې هغه یونانیان هم د خدای کور ته راوستلی دی او دا سپېچلی جای یې ورباندې ناپاکه کری دی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25977, 'Acts 21:29', 'Acts', 21, 29, 'هغوی د دې دپاره دا خبرې وکړې چې له مخکې څخه یې تروفیموس چې د افسیس څخه ؤ، په ښار کې د پولوس سره لیدلی ؤ او فکر یې کاوه چې پولوس هغه د خدای کور ته راوستلی دی.', 'هغوی د دې دپاره دا خبرې وکرې چې له مخکې چخه یې تروفیموس چې د افسیس چخه و، په شار کې د پولوس سره لیدلی و او فکر یې کاوه چې پولوس هغه د خدای کور ته راوستلی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25978, 'Acts 21:30', 'Acts', 21, 30, 'په ټول ښار کې ګډوډي رامنځته شوه او خلکو د هرې خوا څخه رامنډې کړې، پولوس یې ونیو او په راښکلو یې د خدای د کور څخه دباندې راوویست او سمدلاسه د خدای د کور دروازې بندې شوې.', 'په تول شار کې ګدودی رامنجته شوه او خلکو د هرې خوا چخه رامندې کرې، پولوس یې ونیو او په راشکلو یې د خدای د کور چخه دباندې راوویست او سمدلاسه د خدای د کور دروازې بندې شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25979, 'Acts 21:31', 'Acts', 21, 31, 'کله چې خلکو هڅه کوله پولوس ووژني، په دې وخت کې د رومي لښکرو قوماندان ته خبر ورسېده چې په ټول اورشلیم کې غوغا جوړه شوې ده.', 'کله چې خلکو هچه کوله پولوس ووژنی، په دې وخت کې د رومی لشکرو قوماندان ته خبر ورسېده چې په تول اورشلیم کې غوغا جوره شوې ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_21_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
